24	class RankGraphV1 : public RankGraph {
25	    struct RankGraphInfo {
26	        RankInfo_t rankInfo;
27	        std::vector<EndpointDesc> endPoints;
28	    };
29	
30	    enum class HcclNetLayerlevel {
31	        HCCL_NetLayer_L0 = 0,
32	        HCCL_NetLayer_L1,
33	        HCCL_NetLayer_L2,
34	        HCCL_NetLayer_MAX,
35	    };
36	
37	public:
38	    HcclResult Init(const RankTable_t& rankTable, const HcclTopoAttr& topoAttr) override;
39	    HcclResult Init(const HcclTopoAttr& topoAttr);
40	    HcclResult
41	    GetLinks(uint32_t netLayer, uint32_t srcRank, uint32_t dstRank, CommLink** linkList, uint32_t* listSize) override;
42	    HcclResult GetHeterogMode(HcclHeterogMode* mode) const override;
43	    const RankInfo_t* FindRank(uint32_t rankId) const;
44	    HcclResult GetRankGraphInfo(GraphType type, void** graph, uint32_t* len) override;
45	    HcclResult GetNetLayers(uint32_t** netLayers, uint32_t* netLayerNum) override;
46	    HcclResult GetDeviceId(uint32_t rankId, uint32_t* deviceId) override;
47	    HcclResult GetInstTopoTypeByNetLayer(uint32_t netLayer, CommTopo* topoType) override;
48	    HcclResult GetInstSizeByNetLayer(uint32_t netLayer, uint32_t* rankNum) override;
49	    HcclResult GetInstRanksByNetLayer(uint32_t netLayer, uint32_t** rankList, uint32_t* rankNum) override;
50	    HcclResult GetInstSizeListByNetLayer(uint32_t netLayer, uint32_t** instSizeList, uint32_t* listSize) override;
51	
52	    HcclResult GetTopoInstsByLayer(uint32_t netLayer, uint32_t** topoInsts, uint32_t* topoInstNum);
53	    HcclResult GetTopoType(uint32_t netLayer, CommTopo* topoType);
54	    HcclResult GetRanksByTopoInst(uint32_t netLayer, uint32_t topoInstId, uint32_t** ranks, uint32_t* rankNum);
55	    std::vector<const RankInfo_t*> GetRanksInTopoInst(uint32_t netLayer, uint32_t topoInstId);
56	    std::set<CommProtocol>
57	    GetProtocolsByConnections(uint32_t netLayer, const std::vector<const RankInfo_t*>& topoInstRanks);
58	    HcclResult GetEndpointNum(uint32_t netLayer, uint32_t topoInstId, uint32_t* num);
59	    HcclResult GetEndpointDesc(uint32_t netLayer, uint32_t topoInstId, uint32_t* descNum, EndpointDesc* endpointDesc);
60	    HcclResult GetEndpointInfo(
61	        uint32_t rankId, const EndpointDesc* endPointDesc, EndpointAttr endpointAttr, uint32_t infoLen,
62	        void* info) override;
63	    HcclResult GetRankSize(uint32_t* rankSize) override;
64	    HcclResult GetDevicePort(const uint32_t rank, uint32_t* devPort) override;
65	
66	private:
67	    const EndpointDesc* MatchEndpointByAddr(const RankGraphInfo& rankGraphInfo, const EndpointDesc* endPointDesc) const;
68	    HcclResult
69	    FillAttr(EndpointAttr endpointAttr, const EndpointDesc* foundEndpoint, uint32_t infoLen, void* info) const;
70	    HcclResult DevTypeToCommProtocol(DevType& type, CommProtocol& protocol) const;
71	    HcclResult
72	    BuildRankGraphInfo(const RankInfo_t& rankItem, const CommProtocol& protocol, RankGraphInfo& outInfo) const;
73	    CommProtocol GetCommProtocolFromRankInfo(const RankInfo_t& srcInfo, const RankInfo_t& dstInfo, uint32_t netLayer);
74	    HcclResult InitRankInfo();
75	    HcclResult InitServerRankInfo();
76	    HcclResult InitSuperPodRankInfo();
77	    HcclResult InitNetLayer();
78	    HcclResult InitGraphRankInfo();
79	    CommProtocol GetCommProtocolInSameServer(const RankInfo_t& srcInfo, const RankInfo_t& dstInfo);
80	    CommProtocol GetCommProtocolBetweenServers(const RankInfo_t& srcInfo, const RankInfo_t& dstInfo) const;
81	    bool NeedIgnoreEndPoints(CommProtocol srcProtocol, CommProtocol dstProtocol, CommProtocol linkProtocol) const;
82	    void PrintLinksInfo(CommLink& link) const;
83	    bool IsRoceInSameServer(uint32_t netLayer, const RankInfo_t& srcInfo, const RankInfo_t& dstInfo);
84	    HcclResult InitHeterogMode();
85	    RankTable_t rankTable_;
86	    std::unordered_map<uint32_t, RankGraphInfo> rankIndex_;
87	    std::map<std::tuple<uint32_t, uint32_t, uint32_t>, std::vector<CommLink>> rankPairInfo_;
88	    std::vector<uint32_t> netLayer_;
