28	HcclResult RankGraphV1::DevTypeToCommProtocol(DevType& type, CommProtocol& protocol) const
29	{
30	    CHK_RET(hrtGetDeviceType(type));
31	    switch (type) {
32	        case DevType::DEV_TYPE_910B:
33	        case DevType::DEV_TYPE_910_93:
34	        case DevType::DEV_TYPE_910:
35	            protocol = CommProtocol::COMM_PROTOCOL_ROCE;
36	            break;
37	        case DevType::DEV_TYPE_310P1:
38	        case DevType::DEV_TYPE_310P3:
39	            protocol = CommProtocol::COMM_PROTOCOL_PCIE;
40	            break;
41	        case DevType::DEV_TYPE_NOSOC:
42	            protocol = CommProtocol::COMM_PROTOCOL_PCIE;
43	            break;
44	        case DevType::DEV_TYPE_950:
45	        case DevType::DEV_TYPE_960:
46	            // 待扩展UB的协议，当前先不支持
47	            protocol = CommProtocol::COMM_PROTOCOL_RESERVED;
48	            break;
49	        default:
50	            HCCL_ERROR("[RankGraphV1] Unknown comm devType: %d", type);
51	            return HCCL_E_PARA;
52	    }
53	    return HCCL_SUCCESS;
54	}
55	
56	HcclResult
57	RankGraphV1::BuildRankGraphInfo(const RankInfo_t& rankItem, const CommProtocol& protocol, RankGraphInfo& outInfo) const
58	{
59	    HCCL_INFO(
60	        "[RankGraphV1][%s] rankId[%u] serverId[%s] serverIdx[%u] superDeviceId[%u] superPodId[%s] "
61	        "devicePhyId[%d]",
62	        __func__, rankItem.rankId, rankItem.serverId.c_str(), rankItem.serverIdx, rankItem.superDeviceId,
63	        rankItem.superPodId.c_str(), rankItem.deviceInfo.devicePhyId);
64	    outInfo.rankInfo = rankItem;
65	    std::vector<HcclIpAddress> addrs = rankItem.deviceInfo.deviceIp;
66	    for (const auto& addr : addrs) {
67	        EndpointDesc point;
68	        CHK_RET(static_cast<HcclResult>(EndpointDescInit(&point, 1)));
69	
70	        // 初始化ROCE协议的基础点位信息
71	        if (addr.IsIPv6()) {
72	            point.commAddr.type = COMM_ADDR_TYPE_IP_V6;
73	            point.commAddr.addr6 = addr.GetBinaryAddress().addr6;
74	        } else {
75	            point.commAddr.type = COMM_ADDR_TYPE_IP_V4;
76	            point.commAddr.addr = addr.GetBinaryAddress().addr;
77	        }
78	        point.protocol = protocol;
79	        if (rankItem.deviceInfo.nicDeploy == NICDeployment::NIC_DEPLOYMENT_HOST) {
80	            point.loc.locType = ENDPOINT_LOC_TYPE_HOST;
81	        } else {
82	            point.loc.locType = ENDPOINT_LOC_TYPE_DEVICE;
83	        }
84	        point.loc.device.devPhyId = rankItem.deviceInfo.devicePhyId;
85	        point.loc.device.superDevId = rankItem.superDeviceId;
86	        point.loc.device.serverIdx = rankItem.serverIdx;
87	        point.loc.device.superPodIdx = rankItem.superPodIdx;
88	        // ROCE协议
89	        outInfo.endPoints.push_back(std::move(point));
90	
91	        // HCCS 协议
92	        point.loc.locType = ENDPOINT_LOC_TYPE_DEVICE;
93	        if (devType_ == DevType::DEV_TYPE_910B || devType_ == DevType::DEV_TYPE_910_93
94	            || devType_ == DevType::DEV_TYPE_310P1 || devType_ == DevType::DEV_TYPE_310P3) {
95	            EndpointDesc hccsPoint = point;
96	            hccsPoint.protocol = COMM_PROTOCOL_HCCS;
97	            hccsPoint.commAddr.type = COMM_ADDR_TYPE_ID;
98	            outInfo.endPoints.push_back(std::move(hccsPoint));
99	        }
100	
101	        // PCIE 协议
102	        if (devType_ == DevType::DEV_TYPE_910B || devType_ == DevType::DEV_TYPE_310P1
103	            || devType_ == DevType::DEV_TYPE_310P3) {
104	            EndpointDesc pciePoint = point;
105	            pciePoint.protocol = COMM_PROTOCOL_PCIE;
106	            pciePoint.commAddr.type = COMM_ADDR_TYPE_ID;
107	            outInfo.endPoints.push_back(std::move(pciePoint));
108	        }
109	    }
110	    return HCCL_SUCCESS;
111	}
112	
113	HcclResult RankGraphV1::Init(const RankTable_t& rankTable, const HcclTopoAttr& topoAttr)
114	{
115	    rankTable_ = rankTable;
116	    topoAttr_ = topoAttr;
117	    rankIndex_.clear();
118	    rankPairInfo_.clear();
119	    HCCL_INFO("[RankGraphV1][%s] rankNum[%zu]", __func__, rankTable_.rankList.size());
120	    CommProtocol protocol = CommProtocol::COMM_PROTOCOL_RESERVED;
121	    CHK_RET(DevTypeToCommProtocol(devType_, protocol));
122	    // 解析 rankTable，建立 rankId -> RankGraphInfo 映射
123	    for (const auto& r : rankTable.rankList) {
124	        RankGraphInfo info;
125	        CHK_RET(BuildRankGraphInfo(r, protocol, info));
126	        rankIndex_[r.rankId] = std::move(info);
127	    }
128	    rankGraph_ = rankTable_.rankList;
129	    CHK_RET(InitRankInfo());
130	    CHK_RET(InitNetLayer());
131	    CHK_RET(InitHeterogMode());
132	    HCCL_INFO("[RankGraphV1][%s] Init success", __func__);
133	    return HCCL_SUCCESS;
134	}
