136	HcclResult RankGraphV1::Init(const HcclTopoAttr& topoAttr)
137	{
138	    topoAttr_ = topoAttr;
139	    rankIndex_.clear();
140	    rankPairInfo_.clear();
141	    HCCL_INFO("[RankGraphV1][%s] rankNum[%zu]", __func__, rankTable_.rankList.size());
142	    CHK_RET(InitRankInfo());
143	    CHK_RET(InitNetLayer());
144	    CHK_RET(InitHeterogMode());
145	    return HCCL_SUCCESS;
146	}
147	
148	bool RankGraphV1::IsRoceInSameServer(uint32_t netLayer, const RankInfo_t& srcInfo, const RankInfo_t& dstInfo)
149	{
150	    // 910B单机两种使能RoCE场景：1.A+X 两卡分别在两个MESH  2.标卡
151	    uint32_t srcPhyId = srcInfo.deviceInfo.devicePhyId;
152	    uint32_t dstPhyId = dstInfo.deviceInfo.devicePhyId;
153	    uint32_t intraRoceSwitch = GetExternalInputIntraRoceSwitch();
154	    HCCL_INFO(
155	        "[%s] netLayer[%u], devType[%d], srcPhyId[%u], dstPhyId[%u], isStandardCard[%d], isDiffDeviceModule[%d] "
156	        "IntraRoceSwitch[%u]",
157	        __func__, netLayer, devType_, srcPhyId, dstPhyId, topoAttr_.isStandardCard, topoAttr_.isDiffDeviceModule,
158	        intraRoceSwitch);
159	    const uint32_t deviceMeshDivider = DEVICE_PER_MODULE;
160	    if (netLayer == HCCL_NETLAYER_1 && devType_ == DevType::DEV_TYPE_910B) {
161	        bool isSrcInLowerMesh = srcPhyId < deviceMeshDivider;
162	        bool isDstInLowerMesh = dstPhyId < deviceMeshDivider;
163	        bool isSrcInUpperMesh = srcPhyId >= deviceMeshDivider;
164	        bool isDstInUpperMesh = dstPhyId >= deviceMeshDivider;
165	
166	        // 判定是否为跨MESH（一卡在低区、一卡在高区，匹配A+X跨MESH场景）
167	        bool isCrossMesh = (isSrcInLowerMesh || isDstInLowerMesh) && (isSrcInUpperMesh || isDstInUpperMesh);
168	        // 跨MESH或标卡直接满足
169	        bool isMeetRoceCondition = (isCrossMesh && topoAttr_.isDiffDeviceModule) || topoAttr_.isStandardCard;
170	        return isMeetRoceCondition && intraRoceSwitch == 1;
171	    }
172	
173	    // 非910B的NETLAYER_1场景：仅标卡满足条件时取外部配置，否则返回false
174	    return topoAttr_.isStandardCard && intraRoceSwitch == 1 && netLayer == HCCL_NETLAYER_1;
175	}
176	
177	CommProtocol RankGraphV1::GetCommProtocolInSameServer(const RankInfo_t& srcInfo, const RankInfo_t& dstInfo)
178	{
179	    // 310P间链路为PCIE或HCCS
180	    LinkTypeInServer linkType = LinkTypeInServer::RESERVED_LINK_TYPE;
181	    hrtGetPairDeviceLinkType(srcInfo.deviceInfo.devicePhyId, dstInfo.deviceInfo.devicePhyId, linkType);
182	    HCCL_INFO(
183	        "[RankGraphV1][%s] ranks[%u,%u] intra-server linkType[%d]", __func__, srcInfo.rankId, dstInfo.rankId, linkType);
184	    if (linkType == LinkTypeInServer::HCCS_TYPE || linkType == LinkTypeInServer::HCCS_SW_TYPE) {
185	        return CommProtocol::COMM_PROTOCOL_HCCS;
186	    } else if (linkType == LinkTypeInServer::SIO_TYPE) {
187	        return CommProtocol::COMM_PROTOCOL_SIO;
188	    } else if (linkType == LinkTypeInServer::PXI_TYPE) {
189	        bool isDiffDeviceModule = (topoAttr_.isDiffDeviceModule && devType_ == DevType::DEV_TYPE_910B);
190	        bool isRankModEqual = (srcInfo.rankId % DEVICE_PER_MODULE == dstInfo.rankId % DEVICE_PER_MODULE);
191	        bool isMeetPxiCondition = (!isDiffDeviceModule) || (isDiffDeviceModule && isRankModEqual);
192	        return isMeetPxiCondition ? CommProtocol::COMM_PROTOCOL_PCIE : CommProtocol::COMM_PROTOCOL_RESERVED;
193	    }
194	    return CommProtocol::COMM_PROTOCOL_RESERVED;
195	}
196	
197	CommProtocol RankGraphV1::GetCommProtocolBetweenServers(const RankInfo_t& srcInfo, const RankInfo_t& dstInfo) const
198	{
199	    // srcInfo与dstInfo一定是相同数据类型
200	    if (devType_ == DevType::DEV_TYPE_310P3 || devType_ == DevType::DEV_TYPE_310P1) {
201	        return CommProtocol::COMM_PROTOCOL_PCIE;
202	    }
203	    if (devType_ == DevType::DEV_TYPE_910B) {
204	        return CommProtocol::COMM_PROTOCOL_ROCE;
205	    }
206	    HCCL_DEBUG(
207	        "[%s] srcInfo.superPodId %s dstInfo.superPodId %s", __func__, srcInfo.superPodId.c_str(),
208	        dstInfo.superPodId.c_str());
209	    if (devType_ == DevType::DEV_TYPE_910_93) {
210	        // 超节点内链路为HCCS
211	        if (!srcInfo.superPodId.empty() && srcInfo.superPodId == dstInfo.superPodId) {
212	            return CommProtocol::COMM_PROTOCOL_HCCS;
213	        }
214	    }
215	    return CommProtocol::COMM_PROTOCOL_RESERVED;
216	}
217	
218	CommProtocol
219	RankGraphV1::GetCommProtocolFromRankInfo(const RankInfo_t& srcInfo, const RankInfo_t& dstInfo, uint32_t netLayer)
220	{
221	    if (srcInfo.deviceInfo.deviceType != dstInfo.deviceInfo.deviceType) {
222	        HCCL_ERROR(
223	            "[RankGraphV1][%s] srcType[%d] != dstType[%d]", __func__, srcInfo.deviceInfo.deviceType,
224	            dstInfo.deviceInfo.deviceType);
225	        return CommProtocol::COMM_PROTOCOL_RESERVED;
226	    }
227	    // 首先判断是否在同一机内
228	    if (srcInfo.serverIdx == dstInfo.serverIdx) {
229	        if (netLayer == HCCL_NETLAYER_0) {
230	            return GetCommProtocolInSameServer(srcInfo, dstInfo);
231	            // 超节点有HCCL_NETLAYER_1及以上的情况，为HCCS链路，或者同卡不同DIE
232	        } else if (
233	            netLayer == HCCL_NETLAYER_1 && devType_ == DevType::DEV_TYPE_910_93
234	            && (srcInfo.superPodId == dstInfo.superPodId
235	                || GetCommProtocolInSameServer(srcInfo, dstInfo) == CommProtocol::COMM_PROTOCOL_SIO)) {
236	            return CommProtocol::COMM_PROTOCOL_HCCS;
237	        } else if (IsRoceInSameServer(netLayer, srcInfo, dstInfo)) {
238	            return CommProtocol::COMM_PROTOCOL_ROCE;
239	        } else {
240	            // 接了交换机才会有HCCL_NETLAYER_1及以上的情况，当前无法判断是否连接交换机，接了交换机走RDMA
241	            return CommProtocol::COMM_PROTOCOL_RESERVED;
242	        }
243	    }
244	    if (srcInfo.serverIdx != dstInfo.serverIdx) {
245	        if (netLayer == HCCL_NETLAYER_0) {
246	            HCCL_INFO("[RankGraphV1][%s] ranks[%u,%u] not in same server", __func__, srcInfo.rankId, dstInfo.rankId);
247	            return CommProtocol::COMM_PROTOCOL_RESERVED;
248	        }
249	        if (netLayer == HCCL_NETLAYER_1) {
250	            HCCL_INFO(
251	                "[RankGraphV1][%s] ranks[%u,%u] inter-server but same superPod[%s]", __func__, srcInfo.rankId,
252	                dstInfo.rankId, srcInfo.superPodId.c_str());
253	            return GetCommProtocolBetweenServers(srcInfo, dstInfo);
254	            // 跨超走ROCE
255	        } else if (
256	            !srcInfo.superPodId.empty() && srcInfo.superPodId != dstInfo.superPodId && netLayer == HCCL_NETLAYER_2) {
257	            HCCL_INFO(
258	                "[RankGraphV1][%s] ranks[%u,%u] inter-superPod use ROCE", __func__, srcInfo.rankId, dstInfo.rankId);
259	            return CommProtocol::COMM_PROTOCOL_ROCE;
260	        }
261	    }
262	    return CommProtocol::COMM_PROTOCOL_RESERVED;
263	}
264	
265	bool RankGraphV1::NeedIgnoreEndPoints(
266	    CommProtocol srcProtocol, CommProtocol dstProtocol, CommProtocol linkProtocol) const
267	{
268	    if (srcProtocol != dstProtocol) {
269	        return true;
270	    } else {
271	        // 两个hccs endpoints间可能是SIO链路
272	        // A + X 两个mesh间是PCIE链路, 310DUO卡两个DIE间链路是HCCS，主次DIE间是PCIE
273	        if (srcProtocol == COMM_PROTOCOL_HCCS && dstProtocol == COMM_PROTOCOL_HCCS
274	            && linkProtocol == COMM_PROTOCOL_SIO) {
275	            return false;
276	        } else if (dstProtocol != linkProtocol) {
277	            return true;
278	        }
279	    }
280	    return false;
281	}
282	
283	void RankGraphV1::PrintLinksInfo(CommLink& link) const
284	{
285	    // 打印CommLink 头部基础信息
286	    HCCL_INFO(
287	        "[RankGraphV1][%s] link.header.version[%u] magicWord[0x%08x] size[%u] reserved[%u]", __func__,
288	        link.header.version, link.header.magicWord, link.header.size, link.header.reserved);
289	
290	    // 打印【源端】srcEndpointDesc 完整信息
291	    HCCL_INFO(
292	        "[RankGraphV1][%s] srcProtocol[%d] srcCommAddrType[%d] srcLocType[%d] srcDevPhyId[%u] "
293	        "srcSuperDevId[%u] srcServerIdx[%u] srcSuperPodIdx[%u]",
294	        __func__, link.srcEndpointDesc.protocol, link.srcEndpointDesc.commAddr.type, link.srcEndpointDesc.loc.locType,
295	        link.srcEndpointDesc.loc.device.devPhyId, link.srcEndpointDesc.loc.device.superDevId,
296	        link.srcEndpointDesc.loc.device.serverIdx, link.srcEndpointDesc.loc.device.superPodIdx);
297	
298	    // 打印【目的端】dstEndpointDesc 完整信息
299	    HCCL_INFO(
300	        "[RankGraphV1][%s] dstProtocol[%d] dstCommAddrType[%d] dstLocType[%d] dstDevPhyId[%u] "
301	        "dstSuperDevId[%u] dstServerIdx[%u] dstSuperPodIdx[%u]",
302	        __func__, link.dstEndpointDesc.protocol, link.dstEndpointDesc.commAddr.type, link.dstEndpointDesc.loc.locType,
303	        link.dstEndpointDesc.loc.device.devPhyId, link.dstEndpointDesc.loc.device.superDevId,
304	        link.dstEndpointDesc.loc.device.serverIdx, link.dstEndpointDesc.loc.device.superPodIdx);
305	
306	    // 打印【链路属性】linkAttr 信息
307	    HCCL_INFO("[RankGraphV1][%s] linkProtocol[%d] hop[%u]", __func__, link.linkAttr.linkProtocol, link.linkAttr.hop);
308	}
