310	HcclResult
311	RankGraphV1::GetLinks(uint32_t netLayer, uint32_t srcRank, uint32_t dstRank, CommLink** linkList, uint32_t* listSize)
312	{
313	    if (rankIndex_.find(srcRank) == rankIndex_.end() || rankIndex_.find(dstRank) == rankIndex_.end()
314	        || FindRank(srcRank) == nullptr || FindRank(dstRank) == nullptr) {
315	        HCCL_ERROR(
316	            "[RankGraphV1][%s] srcRank[%u] or dstRank[%u] is not existed in rankTable", __func__, srcRank, dstRank);
317	        return HCCL_E_PARA;
318	    }
319	
320	    if (netLayer > HCCL_NETLAYER_2) {
321	        HCCL_ERROR(
322	            "[RankGraphV1][%s] srcRank[%u] and dstRank[%u] do not have netLayer[%u]", __func__, srcRank, dstRank,
323	            netLayer);
324	        return HCCL_E_PARA;
325	    }
326	    auto& srcEndpointDescs = rankIndex_[srcRank].endPoints;
327	    auto& dstEndpointDescs = rankIndex_[dstRank].endPoints;
328	
329	    const RankInfo_t& srcInfo = rankIndex_[srcRank].rankInfo;
330	    const RankInfo_t& dstInfo = rankIndex_[dstRank].rankInfo;
331	    CommProtocol protocol = COMM_PROTOCOL_RESERVED;
332	    protocol = GetCommProtocolFromRankInfo(srcInfo, dstInfo, netLayer);
333	    if (protocol == COMM_PROTOCOL_RESERVED) {
334	        HCCL_WARNING("[RankGraphV1][%s] no links between srcRank[%u] dstRank[%u]", __func__, srcRank, dstRank);
335	        *linkList = nullptr;
336	        *listSize = 0;
337	        return HCCL_SUCCESS;
338	    }
339	
340	    // 1. 查询是否有缓存CommLink信息
341	    auto key = std::make_tuple(netLayer, srcRank, dstRank);
342	    auto it = rankPairInfo_.find(key);
343	    if (it == rankPairInfo_.end()) {
344	        // 没有则创建
345	        HCCL_INFO("[RankGraphV1][%s] no cached links, build new srcRank[%u] dstRank[%u]", __func__, srcRank, dstRank);
346	        std::vector<CommLink> links;
347	        for (size_t i = 0; i < srcEndpointDescs.size(); i++) {
348	            for (size_t j = 0; j < dstEndpointDescs.size(); j++) {
349	                if (NeedIgnoreEndPoints(srcEndpointDescs[i].protocol, dstEndpointDescs[j].protocol, protocol)) {
350	                    continue;
351	                }
352	                CommLink link;
353	                CHK_RET(CommLinkInit(&link, 1));
354	
355	                link.srcEndpointDesc = srcEndpointDescs[i];
356	                link.srcEndpointDesc.protocol = protocol;
357	                link.dstEndpointDesc = dstEndpointDescs[j];
358	                link.dstEndpointDesc.protocol = protocol;
359	                link.linkAttr.linkProtocol = protocol;
360	                PrintLinksInfo(link);
361	                links.push_back(std::move(link));
362	            }
363	        }
364	        it = rankPairInfo_.emplace(std::make_tuple(netLayer, srcRank, dstRank), std::move(links)).first;
365	    }
366	    HCCL_INFO(
367	        "[RankGraphV1][%s] links, netLayer[%u] srcRank[%u] dstRank[%u] protocol[%d]", __func__, netLayer, srcRank,
368	        dstRank, protocol);
369	
370	    auto& links = it->second;
371	    *listSize = static_cast<uint32_t>(links.size());
372	    if (links.empty()) {
373	        *linkList = nullptr;
374	        HCCL_ERROR("[RankGraphV1][%s] links empty for srcRank[%u] dstRank[%u]", __func__, srcRank, dstRank);
375	    } else {
376	        *linkList = links.data(); // 连续数组首地址
377	        HCCL_INFO(
378	            "[RankGraphV1][%s] srcRank[%u] dstRank[%u] linkList[%p] linkNum[%u]", __func__, srcRank, dstRank, *linkList,
379	            *listSize);
380	    }
381	
382	    return HCCL_SUCCESS;
383	}
