385	HcclResult RankGraphV1::InitHeterogMode()
386	{
387	    if (topoAttr_.rankInfoList.empty()) {
388	        HCCL_ERROR("[RankGraphV1][%s] invalid para. rankInfoList is empty", __func__);
389	        return HCCL_E_INTERNAL;
390	    }
391	
392	    std::set<DevType> devTypes;
393	    for (u32 index = 0; index < topoAttr_.rankInfoList.size(); index++) {
394	        devTypes.insert(topoAttr_.rankInfoList[index].deviceType);
395	    }
396	
397	    // 只包含一种芯片的同构组网
398	    if (devTypes.size() == 1) {
399	        heterogMode_ = HcclHeterogMode::HCCL_HETEROG_MODE_HOMOGENEOUS;
400	        return HCCL_SUCCESS;
401	    }
402	
403	    // 包含两种芯片的异构混合组网
404	    constexpr uint32_t MIX_CHIPS = 2;
405	    if (devTypes.size() == MIX_CHIPS && devTypes.find(DevType::DEV_TYPE_910B) != devTypes.end()
406	        && devTypes.find(DevType::DEV_TYPE_910_93) != devTypes.end()) {
407	        heterogMode_ = HcclHeterogMode::HCCL_HETEROG_MODE_MIX_A2_A3;
408	        return HCCL_SUCCESS;
409	    }
410	
411	    std::string devStr;
412	    for (auto itSet = devTypes.begin(); itSet != devTypes.end(); itSet++) {
413	        if (itSet != devTypes.begin()) {
414	            devStr += ", ";
415	        }
416	        devStr += std::to_string(static_cast<int>(*itSet));
417	    }
418	    HCCL_ERROR(
419	        "[RankGraphV1][%s] Unknown mode[%d], devtypes[%s]", __func__, HcclHeterogMode::HCCL_HETEROG_MODE_INVALID,
420	        devStr.c_str());
421	    return HCCL_E_INTERNAL;
422	}
