577	std::vector<const RankInfo_t*> RankGraphV1::GetRanksInTopoInst(uint32_t netLayer, uint32_t topoInstId)
578	{
579	    std::vector<const RankInfo_t*> ranks;
580	
581	    if (netLayer >= netLayer_.size()) {
582	        return ranks;
583	    }
584	    if (netLayer == static_cast<uint32_t>(HcclNetLayerlevel::HCCL_NetLayer_L0)) {
585	        auto it = serverToRank_.find(topoInstId);
586	        if (it == serverToRank_.end()) {
587	            return ranks;
588	        }
589	        for (const auto& rankInfo : it->second) {
590	            for (const auto& graphInfo : rankGraph_) {
591	                if (graphInfo.rankId == rankInfo.userRank) {
592	                    ranks.push_back(&graphInfo);
593	                }
594	            }
595	        }
596	    } else {
597	        auto listIt = rankList_.find(netLayer);
598	        auto sizeListIt = rankSizeList_.find(netLayer);
599	        if (listIt != rankList_.end() && sizeListIt != rankSizeList_.end()) {
600	            if (topoInstId >= sizeListIt->second.size()) {
601	                return ranks;
602	            }
603	        }
604	
605	        for (uint32_t userRank : listIt->second) {
606	            for (const auto& rankInfo : rankGraph_) {
607	                if (rankInfo.rankId == userRank) {
608	                    ranks.push_back(&rankInfo);
609	                    break;
610	                }
611	            }
612	        }
613	    }
614	    return ranks;
615	}
