617	std::set<CommProtocol>
618	RankGraphV1::GetProtocolsByConnections(uint32_t netLayer, const std::vector<const RankInfo_t*>& topoInstRanks)
619	{
620	    std::set<CommProtocol> protocols;
621	
622	    const RankInfo_t* srcRankInfo = nullptr;
623	    for (const auto& rankInfo : rankGraph_) {
624	        if (rankInfo.rankId == rankData_.userRank) {
625	            srcRankInfo = &rankInfo;
626	            break;
627	        }
628	    }
629	    if (srcRankInfo == nullptr) {
630	        return protocols;
631	    }
632	
633	    for (const RankInfo_t* dstRankInfo : topoInstRanks) {
634	        if (dstRankInfo->rankId == rankData_.userRank) {
635	            continue;
636	        }
637	
638	        CommProtocol protocol = GetCommProtocolFromRankInfo(*srcRankInfo, *dstRankInfo, netLayer);
639	        if (protocol != COMM_PROTOCOL_RESERVED) {
640	            protocols.insert(protocol);
641	        }
642	    }
643	
644	    return protocols;
645	}
