647	HcclResult RankGraphV1::GetEndpointNum(uint32_t netLayer, uint32_t topoInstId, uint32_t* num)
648	{
649	    if (netLayer >= netLayer_.size()) {
650	        HCCL_ERROR("[RankGraphV1][%s] invalid para. netlayer[%u]", __func__, netLayer);
651	        return HCCL_E_PARA;
652	    }
653	    if (rankIndex_.empty()) {
654	        HCCL_ERROR("[RankGraphV1][%s] rankIndex is empty", __func__);
655	        return HCCL_E_INTERNAL;
656	    }
657	    std::vector<const RankInfo_t*> topoInstRanks = GetRanksInTopoInst(netLayer, topoInstId);
658	    if (topoInstRanks.empty()) {
659	        *num = 0;
660	        return HCCL_SUCCESS;
661	    }
662	
663	    std::set<CommProtocol> protocols = GetProtocolsByConnections(netLayer, topoInstRanks);
664	    if (protocols.empty()) {
665	        HCCL_INFO(
666	            "[RankGraphV1][%s] no protocols found for netlayer [%u] topoInstId[%u]", __func__, netLayer, topoInstId);
667	    }
668	
669	    const RankGraphInfo* currentRankInfo = nullptr;
670	    for (auto& pair : rankIndex_) {
671	        if (pair.second.rankInfo.rankId == rankData_.userRank) {
672	            currentRankInfo = &pair.second;
673	            break;
674	        }
675	    }
676	    if (currentRankInfo == nullptr) {
677	        return HCCL_E_INTERNAL;
678	    }
679	
680	    uint32_t count = 0;
681	    for (const auto& endpoint : currentRankInfo->endPoints) {
682	        if (protocols.find(endpoint.protocol) != protocols.end()) {
683	            count++;
684	        }
685	    }
686	    *num = count;
687	
688	    return HCCL_SUCCESS;
689	}
