692	RankGraphV1::GetEndpointDesc(uint32_t netLayer, uint32_t topoInstId, uint32_t* descNum, EndpointDesc* endpointDesc)
693	{
694	    if (netLayer >= netLayer_.size()) {
695	        HCCL_ERROR("[RankGraphV1][%s] invalid para. netlayer[%u]", __func__, netLayer);
696	        return HCCL_E_PARA;
697	    }
698	    if (descNum == nullptr || endpointDesc == nullptr) {
699	        HCCL_ERROR("[RankGraphV1][%s] invalid para. null ptr", __func__);
700	        return HCCL_E_PARA;
701	    }
702	    if (rankIndex_.empty()) {
703	        HCCL_ERROR("[RankGraphV1][%s] rankIndex is empty", __func__);
704	        return HCCL_E_INTERNAL;
705	    }
706	    std::vector<const RankInfo_t*> topoInstRanks = GetRanksInTopoInst(netLayer, topoInstId);
707	    if (topoInstRanks.empty()) {
708	        *descNum = 0;
709	        return HCCL_SUCCESS;
710	    }
711	
712	    std::set<CommProtocol> protocols = GetProtocolsByConnections(netLayer, topoInstRanks);
713	    if (protocols.empty()) {
714	        HCCL_INFO(
715	            "[RankGraphV1][GetEndpointDesc] no protocols found, netlayer [%u] topoInstId[%u]", netLayer, topoInstId);
716	    }
717	
718	    const RankGraphInfo* currRankInfo = nullptr;
719	    for (auto& pair : rankIndex_) {
720	        if (pair.second.rankInfo.rankId == rankData_.userRank) {
721	            currRankInfo = &pair.second;
722	            break;
723	        }
724	    }
725	    if (currRankInfo == nullptr) {
726	        return HCCL_E_INTERNAL;
727	    }
728	
729	    uint32_t count = 0;
730	    for (const auto& endpoint : currRankInfo->endPoints) {
731	        if (protocols.find(endpoint.protocol) != protocols.end()) {
732	            if (count >= *descNum) {
733	                return HCCL_E_PARA;
734	            }
735	            endpointDesc[count] = endpoint;
736	            count++;
737	        }
738	    }
739	    *descNum = count;
740	
741	    return HCCL_SUCCESS;
742	}
