744	const EndpointDesc*
745	RankGraphV1::MatchEndpointByAddr(const RankGraphInfo& rankGraphInfo, const EndpointDesc* endPointDesc) const
746	{
747	    for (const auto& endpoint : rankGraphInfo.endPoints) {
748	        if (endpoint.commAddr.type != endPointDesc->commAddr.type || endpoint.protocol != endPointDesc->protocol) {
749	            continue;
750	        }
751	        bool matched = false;
752	        switch (endpoint.commAddr.type) {
753	            case COMM_ADDR_TYPE_IP_V4:
754	                matched
755	                    = (memcmp(&endpoint.commAddr.addr, &endPointDesc->commAddr.addr, sizeof(endpoint.commAddr.addr))
756	                       == 0);
757	                break;
758	            case COMM_ADDR_TYPE_IP_V6:
759	                matched
760	                    = (memcmp(&endpoint.commAddr.addr6, &endPointDesc->commAddr.addr6, sizeof(endpoint.commAddr.addr6))
761	                       == 0);
762	                break;
763	            case COMM_ADDR_TYPE_ID:
764	                matched = true;
765	                break;
766	            default:
767	                break;
768	        }
769	        if (matched) {
770	            return &endpoint;
771	        }
772	    }
773	    return nullptr;
774	}
