776	HcclResult
777	RankGraphV1::FillAttr(EndpointAttr endpointAttr, const EndpointDesc* foundEndpoint, uint32_t infoLen, void* info) const
778	{
779	    switch (endpointAttr) {
780	        case ENDPOINT_ATTR_BW_COEFF: {
781	            CHK_PRT_RET(
782	                infoLen != sizeof(EndpointAttrBwCoeff),
783	                HCCL_ERROR(
784	                    "[RankGraphV1::GetEndpointInfo] Size mismatch for ENDPOINT_ATTR_BW_COEFF: expected %zu, actual %u",
785	                    sizeof(EndpointAttrBwCoeff), infoLen),
786	                HCCL_E_PARA);
787	            *(static_cast<EndpointAttrBwCoeff*>(info)) = 1;
788	            break;
789	        }
790	        case ENDPOINT_ATTR_DIE_ID: {
791	            CHK_PRT_RET(
792	                infoLen != sizeof(EndpointAttrDieId),
793	                HCCL_ERROR(
794	                    "[RankGraphV1::GetEndpointInfo] Size mismatch for ENDPOINT_ATTR_DIE_ID: expected %zu, actual %u",
795	                    sizeof(EndpointAttrDieId), infoLen),
796	                HCCL_E_PARA);
797	            *(static_cast<EndpointAttrDieId*>(info)) = foundEndpoint->loc.device.superDevId;
798	            break;
799	        }
800	        case ENDPOINT_ATTR_LOCATION: {
801	            CHK_PRT_RET(
802	                infoLen != sizeof(EndpointAttrLocation),
803	                HCCL_ERROR(
804	                    "[RankGraphV1::GetEndpointInfo] Size mismatch for ENDPOINT_ATTR_LOCATION: expected %zu, actual %u",
805	                    sizeof(EndpointAttrLocation), infoLen),
806	                HCCL_E_PARA);
807	            *(static_cast<EndpointAttrLocation*>(info)) = foundEndpoint->loc.locType;
808	            break;
809	        }
810	        default: {
811	            HCCL_ERROR("[RankGraphV1::GetEndpointInfo] Invalid endpointAttr[%d]", endpointAttr);
812	            return HCCL_E_PARA;
813	        }
814	    }
815	    return HCCL_SUCCESS;
816	}
