936	HcclResult RankGraphV1::InitServerRankInfo()
937	{
938	    u32 serverIdx = 0;
939	    auto& rankInfoList = topoAttr_.rankInfoList;
940	    for (u32 index = 0; index < rankInfoList.size(); index++) {
941	        serverIdx = rankInfoList[index].serverIdx;
942	        auto itServer = serverToRank_.find(serverIdx);
943	        if (itServer != serverToRank_.end()) {
944	            itServer->second.push_back(rankInfoList[index]);
945	        } else {
946	            std::vector<RankInfo> rankVecTmp;
947	            rankVecTmp.push_back(rankInfoList[index]);
948	            serverToRank_.insert(std::make_pair(serverIdx, rankVecTmp));
949	        }
950	    }
951	    // 调整每个server内的user_rank排序(server内userRank从小到大,一定连续)
952	    for (auto iterMap = serverToRank_.begin(); iterMap != serverToRank_.end(); iterMap++) {
953	        if (!(iterMap->second).empty()) {
954	            std::sort(iterMap->second.begin(), iterMap->second.end(), RankGraphSort);
955	        }
956	    }
957	    serverIdx = rankData_.serverIdx;
958	    auto rankVec = serverToRank_.find(serverIdx);
959	    if (rankVec != serverToRank_.end()) {
960	        std::string rankIdListServer;
961	        for (auto iter : serverToRank_[serverIdx]) {
962	            rankIdListServer += std::to_string(iter.userRank) + " ";
963	        }
964	        HCCL_INFO(
965	            "[RankGraphV1][%s] devtype[%d], curRank[%u], serverToRanklist[%s]", __func__, topoAttr_.deviceType,
966	            rankData_.userRank, rankIdListServer.c_str());
967	    }
968	    return HCCL_SUCCESS;
969	}
