971	HcclResult RankGraphV1::InitSuperPodRankInfo()
972	{
973	    auto& rankInfoList = topoAttr_.rankInfoList;
974	    for (u32 index = 0; index < rankInfoList.size(); index++) {
975	        // 填充superPodRankMap_, 记录superPodId -> rankInfo
976	        HCCL_DEBUG(
977	            "[RankGraphV1][%s] superPodIdx[%u],superPodId[%s]", __func__, rankInfoList[index].superPodIdx,
978	            rankInfoList[index].superPodId.c_str());
979	        auto itSuperPod = superPodToRank_.find(rankInfoList[index].superPodIdx);
980	        if (itSuperPod != superPodToRank_.end()) {
981	            itSuperPod->second.push_back(rankInfoList[index]);
982	        } else {
983	            std::vector<RankInfo> rankVecTmp;
984	            rankVecTmp.push_back(rankInfoList[index]);
985	            superPodToRank_.insert(std::make_pair(rankInfoList[index].superPodIdx, rankVecTmp));
986	        }
987	    }
988	
989	    // 调整每个superPod内的user_rank排序, 按照serverIdx从小到大、userRank从小到大排序
990	    for (auto iterMap = superPodToRank_.begin(); iterMap != superPodToRank_.end(); iterMap++) {
991	        if (!(iterMap->second).empty()) {
992	            std::sort(iterMap->second.begin(), iterMap->second.end(), RankGraphSort);
993	        }
994	    }
995	
996	    if (superPodToRank_.find(rankData_.superPodIdx) != superPodToRank_.end()) {
997	        std::string rankIdListPod;
998	        for (auto iter : superPodToRank_[rankData_.superPodIdx]) {
999	            rankIdListPod += std::to_string(iter.userRank) + " ";
1000	        }
1001	        HCCL_INFO(
1002	            "[RankGraphV1][%s] curRank[%u], curSuperPod[%s] superPodToRanklist[%s]", __func__, rankData_.userRank,
1003	            rankData_.superPodId.c_str(), rankIdListPod.c_str());
1004	    }
1005	    return HCCL_SUCCESS;
