1008	HcclResult RankGraphV1::InitNetLayer()
1009	{
1010	    netLayer_.clear();
1011	    netLayer_.push_back(static_cast<uint32_t>(HcclNetLayerlevel::HCCL_NetLayer_L0));
1012	
1013	    u32 serverIdx = rankData_.serverIdx;
1014	    auto rankVec = serverToRank_.find(serverIdx);
1015	    if (rankVec == serverToRank_.end()) {
1016	        HCCL_ERROR("[RankGraphV1][%s] find serverToRank failed, serverIdx[%u]", __func__, serverIdx);
1017	        return HCCL_E_INTERNAL;
1018	    }
1019	    std::vector<u32> rankListTmp;
1020	    for (auto iter : serverToRank_[serverIdx]) {
1021	        rankListTmp.push_back(iter.userRank);
1022	    }
1023	    rankList_.insert({static_cast<uint32_t>(HcclNetLayerlevel::HCCL_NetLayer_L0), rankListTmp});
1024	
1025	    std::vector<u32> rankSizeListTmp;
1026	    for (auto iter : serverToRank_) {
1027	        rankSizeListTmp.push_back(iter.second.size());
1028	    }
1029	    rankSizeList_.insert({static_cast<uint32_t>(HcclNetLayerlevel::HCCL_NetLayer_L0), rankSizeListTmp});
1030	
1031	    DevType deviceType = topoAttr_.deviceType;
1032	    if (serverToRank_.size() > 1) {
1033	        netLayer_.push_back(static_cast<uint32_t>(HcclNetLayerlevel::HCCL_NetLayer_L1));
1034	        if (deviceType == DevType::DEV_TYPE_910B || deviceType == DevType::DEV_TYPE_910) {
1035	            std::vector<u32> rankListTmp1;
1036	            for (auto& pair : serverToRank_) {
1037	                for (auto iter : pair.second) {
1038	                    rankListTmp1.push_back(iter.userRank);
1039	                }
1040	            }
1041	            rankList_.insert({static_cast<uint32_t>(HcclNetLayerlevel::HCCL_NetLayer_L1), rankListTmp1});
1042	            rankSizeList_.insert(
1043	                {static_cast<uint32_t>(HcclNetLayerlevel::HCCL_NetLayer_L1), {topoAttr_.userRankSize}});
1044	        } else if (deviceType == DevType::DEV_TYPE_910_93) {
1045	            auto it = superPodToRank_.find(rankData_.superPodIdx);
1046	            if (it == superPodToRank_.end()) {
1047	                HCCL_ERROR(
1048	                    "[RankGraphV1][%s] find superPodToRank_ failed, superPodIdx[%u]", __func__, rankData_.superPodIdx);
1049	                return HCCL_E_INTERNAL;
1050	            }
1051	            std::vector<u32> rankListTmp1;
1052	            for (auto iter : superPodToRank_[rankData_.superPodIdx]) {
1053	                rankListTmp1.push_back(iter.userRank);
1054	            }
1055	            std::vector<u32> rankSizeListTmp1;
1056	            for (auto iter : superPodToRank_) {
1057	                rankSizeListTmp1.push_back(iter.second.size());
1058	            }
1059	            rankList_.insert({static_cast<uint32_t>(HcclNetLayerlevel::HCCL_NetLayer_L1), rankListTmp1});
1060	            rankSizeList_.insert({static_cast<uint32_t>(HcclNetLayerlevel::HCCL_NetLayer_L1), rankSizeListTmp1});
1061	        }
1062	    }
1063	
1064	    if (deviceType == DevType::DEV_TYPE_910_93 && superPodToRank_.size() > 1) {
1065	        netLayer_.push_back(static_cast<uint32_t>(HcclNetLayerlevel::HCCL_NetLayer_L2));
1066	        std::vector<u32> rankListTmp2;
1067	        for (const auto& pair : superPodToRank_) {
1068	            for (auto iter : pair.second) {
1069	                rankListTmp2.push_back(iter.userRank);
1070	            }
1071	        }
1072	        rankList_.insert({static_cast<uint32_t>(HcclNetLayerlevel::HCCL_NetLayer_L2), rankListTmp2});
1073	        rankSizeList_.insert({static_cast<uint32_t>(HcclNetLayerlevel::HCCL_NetLayer_L2), {topoAttr_.userRankSize}});
1074	    }
1075	    return HCCL_SUCCESS;
1076	}
